import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DNL3hc5c.js";const p=JSON.parse('{"title":"📜 Version 1.x History","description":"","frontmatter":{},"headers":[],"relativePath":"doc/8-project-and-support/releases/v1.x.md","filePath":"doc/8-project-and-support/releases/v1.x.md"}'),i={name:"doc/8-project-and-support/releases/v1.x.md"};function n(s,e,d,c,l,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="📜-version-1-x-history" tabindex="-1">📜 Version 1.x History <a class="header-anchor" href="#📜-version-1-x-history" aria-label="Permalink to &quot;📜 Version 1.x History&quot;">​</a></h1><h2 id="v1-1-3-2026-03-31" tabindex="-1">[v1.1.3] - 2026-03-31 <a class="header-anchor" href="#v1-1-3-2026-03-31" aria-label="Permalink to &quot;[v1.1.3] - 2026-03-31&quot;">​</a></h2><h3 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h3><p>Browser: persistent storage wrapper, multi‑tap gesture helper, geolocation + maps/address utilities, simple alert/prompt/confirm helpers. Server: sandboxed temp‑file API, HTTP helpers with timeouts, Base64 encode/decode, JWT payload decoder. Tempo v2.0.0: lazy initialization, unified Term math/format tokens (#{...}), anchor/term utilities and faster startup.</p><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><p>Expanded API/type docs, architecture, benchmarks, migration and cookbook guidance.</p><h3 id="branding" tabindex="-1">Branding <a class="header-anchor" href="#branding" aria-label="Permalink to &quot;Branding&quot;">​</a></h3><p>Package scope renamed to @magmacomputing/*; new build/release scripts and updated TypeScript/test configs.</p><h2 id="v1-1-2-2026-03-23" tabindex="-1">[v1.1.2] - 2026-03-23 <a class="header-anchor" href="#v1-1-2-2026-03-23" aria-label="Permalink to &quot;[v1.1.2] - 2026-03-23&quot;">​</a></h2><h3 id="new-features-1" tabindex="-1">New Features <a class="header-anchor" href="#new-features-1" aria-label="Permalink to &quot;New Features&quot;">​</a></h3><p>Unified plugin system via Tempo.load() for plugins, Term plugins, and discovery configuration. Made Pledge thenable and awaitable via .then() method support. Enhanced makeTemplate() with safe placeholder substitution instead of code evaluation.</p><h3 id="bug-fixes" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><p>Improved asCurrency() to properly coerce string inputs. Fixed constructor error handling to throw instead of returning empty objects.</p><h3 id="documentation-1" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-1" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><p>Added Target Audience section describing intended users and migration scenarios. Expanded Node.js documentation with native subpath import details.</p><h2 id="v1-1-1-2026-03-22" tabindex="-1">[v1.1.1] - 2026-03-22 <a class="header-anchor" href="#v1-1-1-2026-03-22" aria-label="Permalink to &quot;[v1.1.1] - 2026-03-22&quot;">​</a></h2><h3 id="new-features-2" tabindex="-1">New Features <a class="header-anchor" href="#new-features-2" aria-label="Permalink to &quot;New Features&quot;">​</a></h3><p>Plugin-based extension architecture for extending Tempo functionality Automatic plugin discovery via static Tempo.discover() method New subpath exports for enums, serialisation, Pledge utility, and Ticker plugin</p><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><p>Ticker functionality now available as optional plugin; requires explicit installation Selective immutability for decorated classes instead of full object freeze Core methods (format, add, set) are now protected from overwrites</p><h3 id="documentation-2" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-2" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><p>Comprehensive overhaul reflecting new plugin architecture Dedicated Pledge utility documentation added</p><h2 id="v1-1-0-2026-03-19" tabindex="-1">[v1.1.0] - 2026-03-19 <a class="header-anchor" href="#v1-1-0-2026-03-19" aria-label="Permalink to &quot;[v1.1.0] - 2026-03-19&quot;">​</a></h2><h3 id="new-features-3" tabindex="-1">New Features <a class="header-anchor" href="#new-features-3" aria-label="Permalink to &quot;New Features&quot;">​</a></h3><p>Introduced Tempo.ticker() — reactive clock streams via async-generator (for await...of) or callback subscription with stop control.</p><h3 id="documentation-3" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-3" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><p>Added a dedicated Ticker guide and updated Tempo docs with examples and API reference.</p><h3 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><p>Added unit tests covering callback mode, async-iterator mode and input validation.</p><h3 id="chores" tabindex="-1">Chores <a class="header-anchor" href="#chores" aria-label="Permalink to &quot;Chores&quot;">​</a></h3><p>Bumped package version to 1.1.0.</p>',31)])])}const m=a(i,[["render",n]]);export{p as __pageData,m as default};
